    if(input.target.distance && input.target.distance < 5) return;
  var targetVector = api.vec.subtract(input.target.pose.position, input.position);
  var distanceFromTarget = api.vec.length(targetVector);
  input.target.distance = distanceFromTarget;
  var forward = api.getForwardVector(input.rotation);
  var frontPosition = api.vec.offsetAlong(input.position, forward, 5);

  if(maneuver.vector) if(Math.abs(api.vec.subtract(maneuver.vector, input.position))< 5) maneuver.reset();
  if (maneuver.isOn()) {
    input.target.pose.position = maneuver.vector;
    return;
  }

  var lookahead = distanceFromTarget-8;
  if (lookahead < 10) lookahead = 10;

  var frontHit = api.raycastSpread(
    frontPosition, forward, lookahead, 2, 10,
    { visualize: false, hitColor: 'pink', missColor: 'gray' }
  );

  if (!frontHit.hit) return {};
  frontHit.distance
  var closestObstacle = frontHit.distance;
  var corr = findCorrectionVector(
    api, frontPosition, forward, lookahead, input.rotation, targetVector, closestObstacle
  );

  if (corr) {
    input.target.pose.position = corr;
    maneuver.trigger(corr, 2000);
  }

  return {};
}

/**
 * @param {TransformerRuntimeApi} api
 * @param {Vec3} origin
 * @param {Vec3} forward
 * @param {number} distance
 * @param {Rotation} entityRotation
 * @param {Vec3} targetVector
 * @param {number} closestObstacle
 * @returns {Vec3 | undefined}
 */
function findCorrectionVector(
  /** @type {TransformerRuntimeApi} */ api,
  /** @type {Vec3} */ origin,
  /** @type {Vec3} */ forward,
  /** @type {number} */ distance,
  /** @type {Rotation} */ entityRotation,
  /** @type {Vec3} */ targetVector,
  /** @type {number} */ closestObstacle,
) {
  var up = api.getUpVector(entityRotation);
  var targetDist = api.vec.length(targetVector);
  var farBlend = Math.min(1, Math.max(0, (targetDist - 8) / 32));
  var urgency = obstacleUrgency(closestObstacle);

  var flatToTarget = api.vec.normalize(
    api.vec.projectOntoPlane(targetVector, up)
  );

  var spread = 1 + urgency * 1.5;
  var steps = 40;
  var results = [];

  for (var i = 0; i <= steps; i++) {
    var angle = -spread + (2 * spread * i) / steps;
    var result = evaluateVector(api, origin, forward, up, distance, angle);

    var flatDir = api.vec.normalize(
      api.vec.projectOntoPlane(result.rotation, up)
    );
    var deviation = api.vec.angleBetween(flatDir, flatToTarget);

    var clearance = result.raycast.hit
      ? result.raycast.distance / distance
      : 1;

    var alignment = 1 - deviation / Math.PI;
    var turnSharpness = Math.abs(angle) / spread;

    var wClear = 1 - farBlend * (1 - urgency);
    var wAlign = farBlend * (1 - urgency);

    var score;

    api.watch("urgency", urgency)
    if (urgency >= 1) {
      score = clearance;
      if (!result.raycast.hit) score += 1;
      score += turnSharpness * 0.5;
      if (Math.abs(angle) < spread * 0.35) score -= 1;
    } else {
      score = wClear * clearance + wAlign * alignment;
      if (!result.raycast.hit) score += 0.5;
      score += urgency * turnSharpness * 0.4;
      if (urgency > 0.85 && Math.abs(angle) < spread * 0.35) score -= 1;
    }

    result.angle = angle;
    result.score = score;
    results.push(result);
  }

  results.sort(function (a, b) { return b.score - a.score; });
  var best = results[0];

  var pushDist = distance * (1 - urgency * 0.5) + urgency * 8;

  return api.vec.add(
    origin,
    api.vec.scale(api.vec.normalize(best.rotation), pushDist)
  );
}

/**
 * @typedef {Object} EvaluateVectorResult
 * @property {Vec3} rotation
 * @property {RaycastResult} raycast
 * @property {number} [score]
 * @property {number} [angle]
 */

/**
 * @param {TransformerRuntimeApi} api
 * @param {Vec3} origin
 * @param {Vec3} forward
 * @param {Vec3} up
 * @param {number} distance
 * @param {number} angle
 * @returns {EvaluateVectorResult}
 */
function evaluateVector(
  /** @type {TransformerRuntimeApi} */ api,
  /** @type {Vec3} */ origin,
  /** @type {Vec3} */ forward,
  /** @type {Vec3} */ up,
  /** @type {number} */ distance,
  /** @type {number} */ angle,
) {
  var direction = api.vec.rotateAroundAxis(forward, up, angle);

  return {
    rotation: direction,
    raycast: api.raycastSpread(
      origin, direction, distance, 2, 10,
      { visualize: true, hitColor: 'white', missColor: 'yellow' }
    )
  };
}

