    input.actions.steering_angle = -backOff.direction*5;
    return;
  } else {
    const front = api.vec.offsetAlong(input.position, forward, 5);
    if (api.raycastSpread(front, forward, 1, 2, 10).hit === true) {
      let direction = -input.actions.steering_angle;
      if(input.target.distance && input.target.distance > 10) backOff.trigger(direction*5);
      //api.log("BACKOFF " + direction);
    }
  }
  if (targetSpeed > currentSpeed) input.actions.throttle = 1;
}

/** @returns {TransformOutput | undefined} */
function transform(
  /** @type {TransformInput} */ input,
  /** @type {number} */ dt,
  /** @type {Record<string, unknown>} */ params,
  /** @type {Record<string, unknown>} */ state,
  /** @type {TransformerRuntimeApi} */ api,
) {
  api.visualizeLine(input.position, input.target.pose.position, "red");


  return {};
}

/** @returns {TransformOutput | undefined} */
function transform(
  /** @type {TransformInput} */ input,
  /** @type {number} */ dt,
  /** @type {Record<string, unknown>} */ params,
  /** @type {Record<string, unknown>} */ state,
  /** @type {TransformerRuntimeApi} */ api,
) {
  if(input.target.distance && input.target.distance < 10) return;
  let forward = api.getForwardVector(input.rotation);
  let backward = api.vec.scale(forward, -1);
  let speed = api.vec.getForwardSpeed(input.velocity, forward);
  let frontPosition = api.vec.offsetAlong(input.position, forward, 5);
  let backdPosition = api.vec.offsetAlong(input.position, backward, 5);
  if (speed > 0) {
    let castResult = api.raycastSpread(frontPosition, forward, speed * speed / 300, 2, 8, { visualize: false });
    if (castResult.hit === true) {
      if (speed > 0.1) {
        let breakSpeed = 1 / (castResult.distance + 1) * ((speed * speed) / 200);
        if (breakSpeed > 1) breakSpeed = 1;
        input.actions.brake = breakSpeed;
        input.actions.throttle = 0;
      }
    }
  } else {
    let castResult = api.raycastSpread(backdPosition, backward, speed * speed / 300, 2, 8, { visualize: false });
    if (castResult.hit === true) {
      if (speed < -0.1) {
        let breakSpeed = 1 / (castResult.distance + 1) * ((speed * speed) / 200);
        if (breakSpeed > 1) breakSpeed = 1;
        input.actions.brake = 0;
        input.actions.throttle = breakSpeed;
      }
    }
  }
  return {};
}

var current =0;
var speed = 0;


function transform(input, dt, params, state, api) {
  var SMOOTH_TIME = 0.08; // seconds; lower = snappier
  var targetAngle = api.clamp(api.getAction(input, 'steering_angle'), -1, 1);
  var current = typeof state.steering === 'number' ? state.steering : 0;

  var alpha = 1 - Math.exp(-dt / SMOOTH_TIME);
  var outputAngle = api.clamp(current + alpha * (targetAngle - current), -1, 1);

  state.steering = outputAngle;
  input.actions.steering_angle = outputAngle;
  return {};
}
